-- Ramy, 28 Aug 2026: "I could keep it structured. Yeah. Structured,
-- worksheet would be good."
--
-- Types each of the 50 UCLES 2018 tasks so the page renders a real
-- worksheet instead of one free-text box per task -- Correct/Not buttons
-- where Cambridge asks which sentences are correct, dropdowns where it asks
-- you to match, a short box per word where it asks about ten words in a
-- list. Hand-written per task against the real question text rather than
-- pattern-matched: several tasks look alike in outline and differ in what
-- they actually ask for.
--
-- Shapes: open | parts | rows_text | rows_choice | rows_choice_text |
-- rows_select | checklist. Answers keep living in
-- pre_course_task_responses.response as JSON (response_kind = 'json'),
-- which is exactly why 0237 made that column free-form -- no migration
-- needed to add a shape later.
alter table public.pre_course_task_items add column if not exists shape jsonb;

update public.pre_course_task_items set shape = '{"kind": "parts", "parts": ["In what context will you be doing the CELTA course?", "Do you know what context you will be teaching in after you finish the course?"]}'::jsonb where task_number = 1 and section_id in (select id from public.pre_course_task_sections where source = 'cambridge');
update public.pre_course_task_items set shape = '{"kind": "parts", "parts": ["Think about why you decided to teach adults.", "Think about what you, as an adult, bring to this learning situation.", "Use those ideas to write down what characterises adult learners."]}'::jsonb where task_number = 2 and section_id in (select id from public.pre_course_task_sections where source = 'cambridge');
update public.pre_course_task_items set shape = '{"kind": "parts", "parts": ["What would you want to find out about a group of learners so that you could plan your lessons?", "How would you find out?"]}'::jsonb where task_number = 3 and section_id in (select id from public.pre_course_task_sections where source = 'cambridge');
update public.pre_course_task_items set shape = '{"kind": "open"}'::jsonb where task_number = 4 and section_id in (select id from public.pre_course_task_sections where source = 'cambridge');
update public.pre_course_task_items set shape = '{"kind": "checklist", "pick": 5, "options": ["has a sense of humour", "has a calm presence", "builds rapport", "is approachable", "knows how to listen well to students", "trusts learners", "is patient", "respects individuality", "gives clear information and feedback", "knows about language and learning", "inspires confidence", "is sensitive to learners as people", "paces lessons to match the learners", "is methodical and well-organised", "plans well", "can be authoritative without being distant", "is always learning and developing", "is enthusiastic and inspires enthusiasm", "is friendly", "is honest", "empathises with the learners", "does not complicate things unnecessarily", "is sensitive to the culture and backgrounds of the learners"]}'::jsonb where task_number = 5 and section_id in (select id from public.pre_course_task_sections where source = 'cambridge');
update public.pre_course_task_items set shape = '{"kind": "open"}'::jsonb where task_number = 6 and section_id in (select id from public.pre_course_task_sections where source = 'cambridge');
