update public.pre_course_task_items set shape = '{"kind": "rows_choice", "options": ["Lexical", "Auxiliary"], "rows": ["He watches TV for at least two hours every evening.", "What are you looking for?", "They aren''t going to come.", "What does he want?", "They haven''t been here before.", "He was waiting on the corner."]}'::jsonb where task_number = 10 and section_id in (select id from public.pre_course_task_sections where source = 'cambridge');
