update public.pre_course_task_items set shape = '{"kind": "rows_text", "cols": ["Why did the difficulty occur?", "A more effective instruction"], "rows": ["Jot that down.", "I wonder if you''d mind just looking at question number 4 and then if you could just answer it.", "I''d like you to read the text on page 4 and answer the first three, then compare your answers with the person next to you. After that write a short summary of the story and discuss this with your partner.", "Look at the question at the bottom of the page and think about an answer."]}'::jsonb where task_number = 45 and section_id in (select id from public.pre_course_task_sections where source = 'cambridge');
